sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

	g_form.addInfoMessage('TEST1')
    // Blocca la scelta del table name nel Document picker
    var docField = g_form.getControl('target_id'); // oppure source_id
    if (docField) {
        // imposta il valore corretto e disabilita il menu
        var depValue = g_form.getValue('type');
        g_form.setValue('target_id', ''); // reset documento se cambi tabella
        docField.setAttribute('dependent_table', depValue);
        docField.readOnly = true; // evita che possa essere modificato manualmente
    }


   //Type appropriate comment here, and begin script below

}
